using JetBrains.Annotations;

namespace NCode.Identity.OpenId.Host.Database;

/// <summary>
/// Judges whether the Postgres role the reference OP host runs as is subject to row-level security. A superuser and a
/// role with <c>BYPASSRLS</c> skip every policy, and the owner of a table skips the policies on it unless the table
/// forces them, so a host running as any of them does not get the tenant isolation the policies give.
/// </summary>
// See ADR-1370. The policies are generated by RowLevelSecurity.
[PublicAPI]
public static class RuntimeRolePosture
{
    /// <summary>
    /// The violation reported for a runtime role that is a superuser.
    /// </summary>
    public const string SuperuserViolation = "the role is a superuser (SUPERUSER)";

    /// <summary>
    /// The violation reported for a runtime role that bypasses row-level security.
    /// </summary>
    public const string BypassesRlsViolation = "the role bypasses row-level security (BYPASSRLS)";

    /// <summary>
    /// The violation reported for a runtime role that owns tables in the current schema.
    /// </summary>
    public const string OwnsTablesViolation = "the role owns tables in the current schema";

    /// <summary>
    /// How to fix a violation: the host runs as a role that row-level security applies to.
    /// </summary>
    public const string Remedy =
        "Run the host as a role that is NOSUPERUSER NOBYPASSRLS and does not own the tables; the migration worker's "
        + "owner role owns them, and HostDatabase:RuntimeRole names the role the worker grants access to.";

    /// <summary>
    /// Evaluates the posture of a runtime role.
    /// </summary>
    /// <param name="isSuperuser">Whether the role is a superuser.</param>
    /// <param name="bypassesRls">Whether the role has <c>BYPASSRLS</c>.</param>
    /// <param name="ownsTenantTables">Whether the role owns tables in the current schema.</param>
    /// <returns>The violations, in the order superuser, bypass and ownership; empty when the role is subject to row-level security.</returns>
    public static IReadOnlyList<string> Evaluate(
        bool isSuperuser,
        bool bypassesRls,
        bool ownsTenantTables
    )
    {
        var violations = new List<string>(capacity: 3);

        if (isSuperuser)
            violations.Add(SuperuserViolation);

        if (bypassesRls)
            violations.Add(BypassesRlsViolation);

        if (ownsTenantTables)
            violations.Add(OwnsTablesViolation);

        return violations;
    }
}
